<?php require __DIR__.'/../includes/bootstrap.php';require_admin();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$s=$pdo->prepare('UPDATE orders SET status=? WHERE id=?');$s->execute([$_POST['status']??'جديد',(int)($_POST['id']??0)]);header('Location: orders.php');exit;}$orders=$pdo->query('SELECT * FROM orders ORDER BY created_at DESC')->fetchAll();$page_title='إدارة الطلبات';require __DIR__.'/../includes/header.php';?><main class="container"><h1 class="gold">إدارة الطلبات</h1><?php require __DIR__.'/nav.php';?><div class="panel table-wrap"><table><tr><th>رقم</th><th>العميل</th><th>الجوال</th><th>المدينة</th><th>الإجمالي</th><th>الحالة</th><th>التاريخ</th></tr><?php foreach($orders as $o):?><tr><td>#<?=$o['id']?></td><td><?=e($o['customer_name'])?></td><td><?=e($o['phone'])?></td><td><?=e($o['city'])?></td><td><?=money($o['total'])?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$o['id']?>"><select name="status" onchange="this.form.submit()"><?php foreach(['جديد','قيد التجهيز','تم الشحن','مكتمل','ملغي'] as $status):?><option <?= $o['status']===$status?'selected':''?>><?=$status?></option><?php endforeach;?></select></form></td><td><?=e($o['created_at'])?></td></tr><tr><td colspan="7" class="muted">العنوان: <?=e($o['address'])?> | ملاحظات: <?=e($o['notes'])?><br><?php $d=$pdo->prepare('SELECT product_name,price,quantity FROM order_items WHERE order_id=?');$d->execute([$o['id']]);foreach($d as $it)echo e($it['product_name']).' × '.(int)$it['quantity'].' — '.money($it['price']).' | ';?></td></tr><?php endforeach;?></table><?php if(!$orders):?><p class="empty">لا توجد طلبات بعد.</p><?php endif;?></div></main><?php require __DIR__.'/../includes/footer.php';?>
